    10	const ATTENTION_TONES = new Set(["warn", "danger"]);
    11	
    12	/** A row needs attention when any of its badges is in a warning or danger tone. */
    13	export function summarize(rows: OrderRow[]): DashboardSummary {
    14	  const byTone: Record<string, number> = {};
    15	  const attentionIds: string[] = [];
    16	  for (const row of rows) {
    17	    byTone[row.status.tone] = (byTone[row.status.tone] ?? 0) + 1;
    18	    const badges = [row.status, row.payment, row.shipment].filter((b): b is NonNullable<typeof b> => b !== null);
    19	    if (badges.some((b) => ATTENTION_TONES.has(b.tone))) attentionIds.push(row.id);
    20	  }
