     1	export enum OrderStatus {
     2	  Pending = "PENDING",
     3	  Confirmed = "CONFIRMED",
     4	  Shipped = "SHIPPED",
     5	  Completed = "COMPLETED",
     6	  Cancelled = "CANCELLED",
     7	}
     8	
     9	export interface OrderLine {
    10	  sku: string;
    11	  qty: number;
    12	  unitPrice: number; // minor units (e.g. won)
    13	}
    14	
    15	export interface Order {
    16	  id: string;
    17	  customer: string;
    18	  status: OrderStatus;
    19	  lines: OrderLine[];
    20	  createdAt: number;
    21	}
    22	
    23	export function orderTotal(order: Order): number {
    24	  return order.lines.reduce((sum, l) => sum + l.qty * l.unitPrice, 0);
    25	}
    26	
    27	const TRANSITIONS: Record<OrderStatus, OrderStatus[]> = {
    28	  [OrderStatus.Pending]: [OrderStatus.Confirmed, OrderStatus.Cancelled],
    29	  [OrderStatus.Confirmed]: [OrderStatus.Shipped, OrderStatus.Cancelled],
    30	  [OrderStatus.Shipped]: [OrderStatus.Completed],
    31	  [OrderStatus.Completed]: [],
    32	  [OrderStatus.Cancelled]: [],
    33	};
    34	
    35	export function canTransition(from: OrderStatus, to: OrderStatus): boolean {
    36	  return TRANSITIONS[from].includes(to);
    37	}
    38	
    39	export function isOrderStatus(s: string): s is OrderStatus {
    40	  return (Object.values(OrderStatus) as string[]).includes(s);
    41	}
