src/presenter/orderRowPresenter.ts:20:    status: badgeFor(agg.order.status),
src/presenter/orderRowPresenter.ts:21:    payment: agg.payment ? badgeFor(agg.payment.status) : null,
src/presenter/orderRowPresenter.ts:22:    shipment: agg.shipment ? badgeFor(agg.shipment.status) : null,
