/*
 * Each domain has its own status vocabulary, and the same raw value can mean
 * different things in different domains (e.g. "PENDING" is an order status and
 * a payment status). Badges are therefore looked up within their own kind.
 */
const BADGES_BY_KIND = Object.freeze({
  order: ORDER_BADGES as Readonly<Record<string, Badge>>,
  payment: PAYMENT_BADGES as Readonly<Record<string, Badge>>,
  shipment: SHIPMENT_BADGES as Readonly<Record<string, Badge>>,
});

export type BadgeKind = keyof typeof BADGES_BY_KIND;

const UNKNOWN_TONE = "neutral" as const;

export function badgeFor(kind: BadgeKind, status: string): Badge {
  const badge = BADGES_BY_KIND[kind][status];
  return badge ? { ...badge } : { label: status, tone: UNKNOWN_TONE };
}

export function knownStatuses(kind: BadgeKind): string[] {
  return Object.keys(BADGES_BY_KIND[kind]).sort();
}

